<script lang="ts">
  import Heading from "$lib/components/Heading.svelte";
  import { animate, createDrawable } from "animejs";
  import { onMount } from "svelte";

  function makeRandomHex(length: number) {
    let result = "";
    const characters = "0123456789ABCDEF";
    const charactersLength = characters.length;
    for (let i = 0; i < length; i++) {
      result += characters.charAt(Math.floor(Math.random() * charactersLength));
    }
    return result;
  }

  onMount(async () => {
    await animate("#scanner", {
      opacity: 0,
      duration: 0,
    });

    await animate("#scanner", {
      opacity: 1,
      duration: 500,
    });

    await animate("#scanner", {
      top: "90%",
      opacity: [1, 1, 1, 0],
      duration: 2000,
    }).then(() => {
      animate("#scanner", {
        top: "0%",
        opacity: 0,
        duration: 0,
      });
    });

    await animate(createDrawable(".glyph-line"), {
      draw: ["0 0", "0 1"],
      duration: 5000,
      loop: false,
    });
  });

  let hexBytes = makeRandomHex(128);
</script>

